package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.icu.sepsis.application.Store;import org.icu.sepsis.domain.Domain.*;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.query.Query;import org.junit.jupiter.api.Test;
class SpecialtyEvidenceReuseTest {
 final Instant now=Instant.parse("2026-11-20T08:00:00Z");final MongoTemplate db=mock(MongoTemplate.class);final SpecialtyEvidenceService service=new SpecialtyEvidenceService(new Store(db,"ICU",new ObjectMapper()));
 Patient patient(){var p=new Patient();p.id="synthetic";p.encounterId="stay";p.department="ICU";p.birthDate=LocalDate.of(1980,1,1);return p;}
 Observation obs(Patient p,String code,double value,String unit){var o=new Observation();o.patientId=p.id;o.encounterId=p.encounterId;o.department=p.department;o.parameterCode=code;o.value=value;o.unit=unit;o.eventTime=now.minusSeconds(600);o.qualityStatus="valid";return o;}
 Map<String,Object> module(Map<String,Object> packet,String key){return ((List<Map<String,Object>>)packet.get("modules")).stream().filter(m->key.equals(m.get("key"))).findFirst().orElseThrow();}
 @Test void automaticObservationsCanReceiveLabelsWithoutFailingTheWholePacket(){var p=patient();var r=service.assess(p,now,List.of(obs(p,"CREA",120,"μmol/L"),obs(p,"PLT",80,"10^9/L"),obs(p,"RASS",-4,"score"),obs(p,"PF_RATIO",180,"mmHg")),Map.of());assertEquals(5,((List<?>)r.get("modules")).size());assertEquals("not_assessable",module(r,"delirium").get("status"));var evidence=(List<Map<String,Object>>)module(r,"aki").get("evidence");assertEquals("当前肌酐",evidence.get(0).get("fieldLabel"));}
 @Test void expiredManualAgeCannotInvalidateCurrentSourceAge(){var p=patient();var review=new SpecialtyEvidenceService.Record();review.id="synthetic-review";var adult=new SpecialtyEvidenceService.Value();adult.flag=false;adult.observedAt=now.minus(Duration.ofDays(2));review.values=Map.of("adult",adult);when(db.findOne(any(Query.class),eq(SpecialtyEvidenceService.Record.class))).thenReturn(review);var r=module(service.assess(p,now,List.of(obs(p,"RASS",-4,"score")),Map.of()),"delirium");assertEquals("not_assessable",r.get("status"));assertTrue(((List<?>)r.get("conflicts")).isEmpty());}

 @Test void staleManualRassDoesNotOverrideTheShorterBedsideContextWindow(){var p=patient();var review=new SpecialtyEvidenceService.Record();review.id="synthetic-review";var rass=new SpecialtyEvidenceService.Value();rass.number=-4d;rass.unit="score";rass.observedAt=now.minus(Duration.ofHours(5));review.values=Map.of("rass",rass);when(db.findOne(any(Query.class),eq(SpecialtyEvidenceService.Record.class))).thenReturn(review);assertEquals("unknown",module(service.assess(p,now,List.of(),Map.of()),"delirium").get("status"));}
 @Test void equivalentUnitsAreReusedWithoutConvertingDifferentPhysicalUnits(){var p=patient();var r=service.assess(p,now,List.of(obs(p,"CREA",120,"µmol/L"),obs(p,"PLT",80,"×10^9/L")),Map.of());assertEquals(1,((List<?>)module(r,"aki").get("evidence")).size());assertEquals(1,((List<?>)module(r,"dic").get("evidence")).size());var wrong=service.assess(p,now,List.of(obs(p,"CREA",1.2,"mg/dL")),Map.of());assertTrue(((List<?>)module(wrong,"aki").get("evidence")).isEmpty());}

 SpecialtyEvidenceService.Record review(String field,double number,Instant time){var r=new SpecialtyEvidenceService.Record();r.id="synthetic-review";var v=new SpecialtyEvidenceService.Value();v.number=number;v.unit="score";v.observedAt=time;v.reference="synthetic assessment";r.values=Map.of(field,v);when(db.findOne(any(Query.class),eq(SpecialtyEvidenceService.Record.class))).thenReturn(r);return r;}
 @Test void expiredReviewIsExplainedButNeverAddedToActiveEvidence(){var p=patient();review("rass",-4,now.minus(Duration.ofHours(5)));var m=module(service.assess(p,now,List.of(),Map.of()),"delirium");assertTrue(((List<?>)m.get("evidence")).isEmpty());var issues=(List<Map<String,Object>>)m.get("reviewIssues");assertEquals("expired",issues.get(0).get("status"));assertEquals("RASS",issues.get(0).get("fieldLabel"));}
 @Test void moreRecentSourceWinsAndExplainsWhyManualReviewWasNotUsed(){var p=patient();review("rass",-4,now.minusSeconds(1200));var m=module(service.assess(p,now,List.of(obs(p,"RASS",0,"score")),Map.of()),"delirium");var facts=(List<Map<String,Object>>)m.get("evidence");assertEquals(1,facts.size());assertEquals(0d,facts.get(0).get("value"));assertEquals("superseded",((List<Map<String,Object>>)m.get("reviewIssues")).get(0).get("status"));}
 @Test void equalTimeEqualValueIsOneFactButDifferentValueIsAnExplainedConflict(){var p=patient();review("rass",-4,now.minusSeconds(600));var m=module(service.assess(p,now,List.of(obs(p,"RASS",-4,"score")),Map.of()),"delirium");assertEquals(1,((List<?>)m.get("evidence")).size());assertTrue(((List<?>)m.get("reviewIssues")).isEmpty());var conflict=module(service.assess(p,now,List.of(obs(p,"RASS",0,"score")),Map.of()),"delirium");assertTrue(((List<?>)conflict.get("evidence")).isEmpty());assertEquals("conflict",((List<Map<String,Object>>)conflict.get("reviewIssues")).get(0).get("status"));}
 @Test void exactFreshnessBoundaryIsValidButOneMillisecondOlderIsExcluded(){var p=patient();review("rass",-4,now.minus(Duration.ofHours(4)));assertEquals("not_assessable",module(service.assess(p,now,List.of(),Map.of()),"delirium").get("status"));review("rass",-4,now.minus(Duration.ofHours(4)).minusMillis(1));assertEquals("unknown",module(service.assess(p,now,List.of(),Map.of()),"delirium").get("status"));}
}
